from pathlib import Path
import csv, math, statistics, json
root=Path(__file__).resolve().parents[1]
rows=list(csv.DictReader((root/'build/learn-audit-3.1.csv').open()))
old={r['id']:r for r in csv.DictReader((root/'build/learn-audit-final.csv').open())}
assert len(rows)==69 and all(not r.get('error') for r in rows)
assert all(float(r['null_volume'])==0 for r in rows)
accepted=[r for r in rows if r['accepted']=='1'];blocked=[r for r in rows if r['accepted']!='1']
flipped=[r for r in rows if abs(math.remainder(float(r['angle'])-float(old[r['id']]['angle']),360))>90]
ratios=[(max(float(r[k]) for k in ('cargo_m3','v50','v150'))-min(float(r[k]) for k in ('cargo_m3','v50','v150')))/float(r['cargo_m3']) for r in accepted if float(r['cargo_m3'])>1]
lines=['# LaseScanViewer 3.1 — проверка расширенного выравнивания','',
'Контрольных объёмов нет. Проверка устанавливает работоспособность и самосогласованность алгоритма; абсолютная точность м³ не подтверждена. Единицы BIN неизвестны: для чисел м³ предполагаются миллиметры.','',
'## Изменение поиска','',
'155 начальных вариантов: глобальные углы с шагом 15°, две высоты, доли соответствий 30% / 60%, отдельные проходы по верхней полосе и локальные углы. До восьми различных кандидатов уточняются на трёх разрешениях. Центр X/Y оценивается по квантилям. Сравнение похожих противоположных решений остаётся консервативным. Алгоритм не использует имя файла или максимизацию объёма для выбора поворота.','',
'## Результаты','',
f'- Прочитано {len(rows)} пар без ошибок; принято совмещение {len(accepted)}; требуют ручной проверки: {", ".join(r["id"] for r in blocked) or "нет"}.',
f'- Empty против самого себя: нулевой ложный груз во всех {len(rows)} случаях.',
f'- Медианный размах по шагам 50/100/150: {statistics.median(ratios)*100:.1f}% для принятых оценок больше 1 м³. Это чувствительность к сетке, не погрешность.',
'- Прошли синтетические тесты 37° / 180°, шума, пропусков и скрытой нижней поверхности; аналитические тесты объёма; регрессия 6066 и прогресс поиска.',
'- Проверены x64 на паре 6066 и x86 на Full413 / Belaz49 Reference: совмещение, интерфейс, PNG/HTML/PLY, ROI, сохранность сканов и камеры при сером окружении.','',
'## Пары, где выбран другой разворот','',
'| Пара | Раньше, ° | Теперь, ° | Совпадение теперь | RMS теперь, ед. |','|---|---:|---:|---:|---:|']
for r in sorted(flipped,key=lambda r:r['id']):
 lines.append(f'| {r["id"]} | {float(old[r["id"]]["angle"]):.2f} | {float(r["angle"]):.2f} | {float(r["overlap"])*100:.1f}% | {float(r["rms"]):.1f} |')
lines += ['', '6066: визуально проверено совпадение стороны с выступом кузова; независимых эталонных параметров сдвига и объёма нет. Проценты совпадения получены на выборке точек, а не являются вероятностью правильности. В 3.1 грубая выборка ограничена 2500 точками (раньше 5000); точное уточнение использует до 5000. Метрики версий не являются оценкой физической погрешности.', '', '## Все пары', '', '| Пара | Поворот, ° | Принято | Совпадение | RMS, ед. | Груз, м³* | Отрицательная разность, м³* |', '|---|---:|---|---:|---:|---:|---:|']
for r in sorted(rows,key=lambda r:r['id']):
 lines.append(f'| {r["id"]} | {float(r["angle"]):.2f} | {"Да" if r["accepted"]=="1" else "Нет"} | {float(r["overlap"])*100:.1f}% | {float(r["rms"]):.1f} | {float(r["cargo_m3"]):.2f} | {float(r["negative_m3"]):.2f} |')
lines += ['', '*Все м³ условны при мм. Для отклонённых решений таблица и CSV содержат принудительный диагностический расчёт; приложение не принимает эти совмещения автоматически.', '', 'Исходные BIN не изменены. Сырые результаты: `Learn-results.csv`, предыдущая версия: `Learn-before.csv`. Весь Learn использовался при разработке; метки development/validation в CSV не означают независимую слепую проверку. Выравнивание сохраняет вертикальную ось: наклон X/Y, масштаб и деформация не восстанавливаются.']
(root/'Learn-alignment-3.1.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps({'pairs':len(rows),'accepted':len(accepted),'blocked':[r['id'] for r in blocked],'reversed':[r['id'] for r in flipped],'median_step_span_percent':statistics.median(ratios)*100}))
